using Employee_Attendance_Salary_Management.Models;
using Npgsql;
using NpgsqlTypes;

namespace Employee_Attendance_Salary_Management.Services;

public sealed class PayrollService
{
    public async Task<IReadOnlyList<PayComponentItem>> GetComponentsAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT id,code,name,component_type,calculation_method,taxable,pensionable,display_order,is_active FROM payroll.pay_component ORDER BY is_active DESC,display_order,lower(name)",c);await using var r=await q.ExecuteReaderAsync();var a=new List<PayComponentItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetBoolean(5),r.GetBoolean(6),r.GetInt32(7),r.GetBoolean(8)));return a;}
    public async Task<IReadOnlyList<PayrollPeriodItem>> GetPeriodsAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT id,period_code,start_date,end_date,payment_date,status FROM payroll.payroll_period ORDER BY start_date DESC",c);await using var r=await q.ExecuteReaderAsync();var a=new List<PayrollPeriodItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetString(1),r.GetFieldValue<DateOnly>(2),r.GetFieldValue<DateOnly>(3),r.GetFieldValue<DateOnly>(4),r.GetString(5)));return a;}
    public async Task<IReadOnlyList<EmployeeComponentItem>> GetEmployeeComponentsAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT x.id,x.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,x.component_id,p.name,p.component_type,x.fixed_amount,x.percentage,x.effective_from,x.effective_to,p.is_active FROM payroll.employee_component x JOIN hr.employee e ON e.id=x.employee_id JOIN payroll.pay_component p ON p.id=x.component_id ORDER BY x.effective_from DESC,lower(e.first_name)",c);await using var r=await q.ExecuteReaderAsync();var a=new List<EmployeeComponentItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetGuid(4),r.GetString(5),r.GetString(6),D(r,7),D(r,8),r.GetFieldValue<DateOnly>(9),ND(r,10),r.GetBoolean(11)));return a;}
    public async Task<IReadOnlyList<PayrollRunItem>> GetRunsAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT r.id,r.payroll_period_id,p.period_code,r.branch_id,b.name,r.run_no,r.status,r.calculation_version,r.started_at,r.completed_at,r.notes FROM payroll.payroll_run r JOIN payroll.payroll_period p ON p.id=r.payroll_period_id LEFT JOIN core.branch b ON b.id=r.branch_id ORDER BY r.created_at DESC",c);await using var r=await q.ExecuteReaderAsync();var a=new List<PayrollRunItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),G(r,3),S(r,4),r.GetInt32(5),r.GetString(6),r.GetString(7),DTO(r,8),DTO(r,9),S(r,10)));return a;}
    public async Task<IReadOnlyList<PayrollResultItem>> GetResultsAsync(Guid? runId=null){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT x.id,x.payroll_run_id,x.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,b.name,d.name,x.base_salary,x.gross_earnings,x.total_deductions,x.employer_contributions,x.net_pay,x.payable_days,x.worked_minutes,x.overtime_minutes,x.unpaid_leave_days,x.status FROM payroll.employee_payroll_result x JOIN hr.employee e ON e.id=x.employee_id JOIN core.branch b ON b.id=x.branch_id JOIN core.department d ON d.id=x.department_id WHERE @run IS NULL OR x.payroll_run_id=@run ORDER BY lower(e.first_name)",c);q.Parameters.Add("run",NpgsqlDbType.Uuid).Value=runId is null?DBNull.Value:runId.Value;await using var r=await q.ExecuteReaderAsync();var a=new List<PayrollResultItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetGuid(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetDecimal(7),r.GetDecimal(8),r.GetDecimal(9),r.GetDecimal(10),r.GetDecimal(11),r.GetDecimal(12),r.GetInt32(13),r.GetInt32(14),r.GetDecimal(15),r.GetString(16)));return a;}

    public async Task SaveComponentAsync(PayComponentForm m,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO payroll.pay_component(code,name,component_type,calculation_method,taxable,pensionable,display_order,is_active,created_by,updated_by) VALUES(@code,@name,@type,@method,@taxable,@pensionable,@order,@active,@actor,@actor)":"UPDATE payroll.pay_component SET name=@name,component_type=@type,calculation_method=@method,taxable=@taxable,pensionable=@pensionable,display_order=@order,is_active=@active,updated_by=@actor WHERE id=@id",c);q.Parameters.AddWithValue("code",m.Id is null?BusinessCode.New("PAYC"):m.Code);q.Parameters.AddWithValue("name",m.Name.Trim());q.Parameters.AddWithValue("type",m.ComponentType);q.Parameters.AddWithValue("method",m.CalculationMethod);q.Parameters.AddWithValue("taxable",m.Taxable);q.Parameters.AddWithValue("pensionable",m.Pensionable);q.Parameters.AddWithValue("order",m.DisplayOrder);q.Parameters.AddWithValue("active",m.IsActive);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id.Value);await q.ExecuteNonQueryAsync();}
    public async Task SetComponentActiveAsync(Guid id,bool active,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand("UPDATE payroll.pay_component SET is_active=@active,updated_by=@actor WHERE id=@id",c);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("active",active);q.Parameters.AddWithValue("actor",actor);await q.ExecuteNonQueryAsync();}
    public async Task SavePeriodAsync(PayrollPeriodForm m,Guid actor){if(m.EndDate<m.StartDate)throw new InvalidOperationException("Period end cannot be before start.");if(m.PaymentDate<m.StartDate)throw new InvalidOperationException("Payment date cannot be before period start.");await using var c=await Open();await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO payroll.payroll_period(period_code,start_date,end_date,payment_date,created_by,updated_by) VALUES(@code,@from,@to,@payment,@actor,@actor)":"UPDATE payroll.payroll_period SET start_date=@from,end_date=@to,payment_date=@payment,updated_at=now(),updated_by=@actor WHERE id=@id AND status='open'",c);q.Parameters.AddWithValue("code",m.Id is null?$"PAY-{m.StartDate:yyyyMM}":m.PeriodCode);q.Parameters.AddWithValue("from",m.StartDate);q.Parameters.AddWithValue("to",m.EndDate);q.Parameters.AddWithValue("payment",m.PaymentDate);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id.Value);if(await q.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Only an open period can be edited.");}
    public async Task SaveEmployeeComponentAsync(EmployeeComponentForm m,Guid actor){if((m.FixedAmount is null)==(m.Percentage is null))throw new InvalidOperationException("Enter either a fixed amount or a percentage.");if(m.EffectiveTo<m.EffectiveFrom)throw new InvalidOperationException("Effective-to cannot be before effective-from.");await using var c=await Open();await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO payroll.employee_component(employee_id,component_id,fixed_amount,percentage,effective_from,effective_to,created_by,updated_by) VALUES(@employee,@component,@fixed,@percentage,@from,@to,@actor,@actor)":"UPDATE payroll.employee_component SET employee_id=@employee,component_id=@component,fixed_amount=@fixed,percentage=@percentage,effective_from=@from,effective_to=@to,updated_by=@actor WHERE id=@id",c);q.Parameters.AddWithValue("employee",m.EmployeeId!.Value);q.Parameters.AddWithValue("component",m.ComponentId!.Value);P(q,"fixed",m.FixedAmount);P(q,"percentage",m.Percentage);q.Parameters.AddWithValue("from",m.EffectiveFrom);P(q,"to",m.EffectiveTo);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id.Value);await q.ExecuteNonQueryAsync();}
    public async Task<Guid> CreateRunAsync(PayrollRunForm m,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand("INSERT INTO payroll.payroll_run(payroll_period_id,branch_id,run_no,status,calculation_version,notes,created_by,updated_by) SELECT @period,@branch,COALESCE(MAX(run_no),0)+1,'draft','v1.0',@notes,@actor,@actor FROM payroll.payroll_run WHERE payroll_period_id=@period AND branch_id IS NOT DISTINCT FROM @branch RETURNING id",c);q.Parameters.AddWithValue("period",m.PeriodId!.Value);P(q,"branch",m.BranchId);q.Parameters.AddWithValue("notes",m.Notes.Trim());q.Parameters.AddWithValue("actor",actor);return (Guid)(await q.ExecuteScalarAsync())!;}
    public async Task CalculateAsync(Guid runId,Guid actor){await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await using(var lockRun=new NpgsqlCommand("UPDATE payroll.payroll_run SET status='calculating',started_at=now(),updated_at=now(),updated_by=@actor WHERE id=@id AND status IN ('draft','calculated')",c,tx)){lockRun.Parameters.AddWithValue("id",runId);lockRun.Parameters.AddWithValue("actor",actor);if(await lockRun.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Only draft or calculated payroll can be recalculated.");}await using(var clear=new NpgsqlCommand("DELETE FROM payroll.employee_payroll_result WHERE payroll_run_id=@id",c,tx)){clear.Parameters.AddWithValue("id",runId);await clear.ExecuteNonQueryAsync();}
        var sql=@"INSERT INTO payroll.employee_payroll_result(payroll_run_id,employee_id,branch_id,department_id,base_salary,gross_earnings,total_deductions,employer_contributions,net_pay,payable_days,worked_minutes,overtime_minutes,unpaid_leave_days,status,created_by,updated_by)
        WITH info AS (SELECT r.id run_id,p.start_date,p.end_date,r.branch_id run_branch FROM payroll.payroll_run r JOIN payroll.payroll_period p ON p.id=r.payroll_period_id WHERE r.id=@run), emp AS (SELECT e.id employee_id,a.branch_id,a.department_id,c.base_salary,i.start_date,i.end_date FROM info i JOIN hr.employee e ON e.employment_status='active' JOIN LATERAL(SELECT branch_id,department_id FROM hr.employee_assignment WHERE employee_id=e.id AND effective_from<=i.end_date AND(effective_to IS NULL OR effective_to>=i.start_date) ORDER BY effective_from DESC LIMIT 1)a ON true JOIN LATERAL(SELECT base_salary FROM hr.employee_compensation WHERE employee_id=e.id AND effective_from<=i.end_date AND(effective_to IS NULL OR effective_to>=i.start_date) ORDER BY effective_from DESC LIMIT 1)c ON true WHERE i.run_branch IS NULL OR a.branch_id=i.run_branch), calc AS (SELECT e.*,((e.end_date-e.start_date)+1)::numeric total_days,COALESCE((SELECT sum(d.day_fraction) FROM leave_mgmt.leave_request_day d JOIN leave_mgmt.leave_request q ON q.id=d.leave_request_id JOIN leave_mgmt.leave_type t ON t.id=q.leave_type_id WHERE q.employee_id=e.employee_id AND q.status='approved' AND NOT t.is_paid AND d.leave_date BETWEEN e.start_date AND e.end_date),0) unpaid,COALESCE((SELECT sum(worked_minutes) FROM attendance.attendance_day WHERE employee_id=e.employee_id AND work_date BETWEEN e.start_date AND e.end_date),0) worked,COALESCE((SELECT sum(overtime_minutes) FROM attendance.attendance_day WHERE employee_id=e.employee_id AND work_date BETWEEN e.start_date AND e.end_date),0) overtime FROM emp e), amounts AS (SELECT c.*,GREATEST(total_days-unpaid,0) payable,COALESCE((SELECT sum(CASE WHEN pc.component_type='earning' THEN COALESCE(ec.fixed_amount,c.base_salary*ec.percentage/100) ELSE 0 END) FROM payroll.employee_component ec JOIN payroll.pay_component pc ON pc.id=ec.component_id WHERE ec.employee_id=c.employee_id AND pc.is_active AND ec.effective_from<=c.end_date AND(ec.effective_to IS NULL OR ec.effective_to>=c.start_date)),0) earnings,COALESCE((SELECT sum(CASE WHEN pc.component_type='deduction' THEN COALESCE(ec.fixed_amount,c.base_salary*ec.percentage/100) ELSE 0 END) FROM payroll.employee_component ec JOIN payroll.pay_component pc ON pc.id=ec.component_id WHERE ec.employee_id=c.employee_id AND pc.is_active AND ec.effective_from<=c.end_date AND(ec.effective_to IS NULL OR ec.effective_to>=c.start_date)),0) deductions,COALESCE((SELECT sum(CASE WHEN pc.component_type='employer_contribution' THEN COALESCE(ec.fixed_amount,c.base_salary*ec.percentage/100) ELSE 0 END) FROM payroll.employee_component ec JOIN payroll.pay_component pc ON pc.id=ec.component_id WHERE ec.employee_id=c.employee_id AND pc.is_active AND ec.effective_from<=c.end_date AND(ec.effective_to IS NULL OR ec.effective_to>=c.start_date)),0) contributions FROM calc c) SELECT @run,employee_id,branch_id,department_id,base_salary,round(base_salary*payable/total_days+earnings,2),round(deductions+base_salary*unpaid/total_days,2),round(contributions,2),round(base_salary*payable/total_days+earnings-deductions,2),payable,worked,overtime,unpaid,'calculated',@actor,@actor FROM amounts";await using(var q=new NpgsqlCommand(sql,c,tx)){q.Parameters.AddWithValue("run",runId);q.Parameters.AddWithValue("actor",actor);await q.ExecuteNonQueryAsync();}await using(var done=new NpgsqlCommand("UPDATE payroll.payroll_run SET status='calculated',completed_at=now(),updated_at=now(),updated_by=@actor WHERE id=@id",c,tx)){done.Parameters.AddWithValue("id",runId);done.Parameters.AddWithValue("actor",actor);await done.ExecuteNonQueryAsync();}await tx.CommitAsync();}
    public async Task SetRunStatusAsync(Guid id,string status,Guid actor){if(status is not("approved" or "cancelled"))throw new InvalidOperationException("Invalid payroll status.");await using var c=await Open();await using var tx=await c.BeginTransactionAsync();var expected=status=="approved"?"calculated":"draft";await using var q=new NpgsqlCommand("UPDATE payroll.payroll_run SET status=@status,approved_by=CASE WHEN @status='approved' THEN @actor ELSE approved_by END,approved_at=CASE WHEN @status='approved' THEN now() ELSE approved_at END,updated_at=now(),updated_by=@actor WHERE id=@id AND status=ANY(@allowed)",c,tx);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("status",status);q.Parameters.AddWithValue("actor",actor);q.Parameters.AddWithValue("allowed",status=="approved"?new[]{"calculated"}:new[]{"draft","calculated"});if(await q.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Payroll run is not in a valid state for this action.");if(status=="approved"){await using var results=new NpgsqlCommand("UPDATE payroll.employee_payroll_result SET status='approved',updated_at=now(),updated_by=@actor WHERE payroll_run_id=@id",c,tx);results.Parameters.AddWithValue("id",id);results.Parameters.AddWithValue("actor",actor);await results.ExecuteNonQueryAsync();}await tx.CommitAsync();}
    public async Task SetResultHoldAsync(Guid id,bool hold,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand("UPDATE payroll.employee_payroll_result x SET status=@status,updated_at=now(),updated_by=@actor FROM payroll.payroll_run r WHERE x.id=@id AND r.id=x.payroll_run_id AND r.status IN ('draft','calculated') AND x.status IN ('calculated','held')",c);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("status",hold?"held":"calculated");q.Parameters.AddWithValue("actor",actor);if(await q.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Salary can only be held or released before payroll approval.");}
    public async Task ClosePeriodAsync(Guid id,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand("UPDATE payroll.payroll_period p SET status='closed',locked_at=now(),locked_by=@actor,updated_at=now(),updated_by=@actor WHERE p.id=@id AND p.status='open' AND EXISTS(SELECT 1 FROM payroll.payroll_run r WHERE r.payroll_period_id=p.id AND r.status IN ('approved','posted')) AND NOT EXISTS(SELECT 1 FROM payroll.payroll_run r WHERE r.payroll_period_id=p.id AND r.status IN ('draft','calculating','calculated'))",c);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("actor",actor);if(await q.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Period can close only after payroll approval and when no draft/calculated runs remain.");}
    public async Task PostRunAsync(Guid id,Guid actor){await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await using(var check=new NpgsqlCommand("SELECT count(*) FROM payroll.employee_payroll_result WHERE payroll_run_id=@id AND status='held'",c,tx)){check.Parameters.AddWithValue("id",id);if((long)(await check.ExecuteScalarAsync())!>0)throw new InvalidOperationException("Release all held employee salaries before posting payroll.");}Guid expense,payable;await using(var accounts=new NpgsqlCommand("SELECT system_code,id FROM finance.ledger_account WHERE system_code IN ('SALARY_EXPENSE','SALARY_PAYABLE') AND is_active",c,tx)){await using var r=await accounts.ExecuteReaderAsync();Guid? e=null,p=null;while(await r.ReadAsync()){if(r.GetString(0)=="SALARY_EXPENSE")e=r.GetGuid(1);else p=r.GetGuid(1);}expense=e??throw new InvalidOperationException("Create active Finance ledger account with system code SALARY_EXPENSE.");payable=p??throw new InvalidOperationException("Create active Finance ledger account with system code SALARY_PAYABLE.");}var branches=new List<(Guid Branch,decimal Gross,decimal Net)>();await using(var totals=new NpgsqlCommand("SELECT branch_id,sum(gross_earnings+employer_contributions),sum(net_pay) FROM payroll.employee_payroll_result WHERE payroll_run_id=@id GROUP BY branch_id",c,tx)){totals.Parameters.AddWithValue("id",id);await using var r=await totals.ExecuteReaderAsync();while(await r.ReadAsync())branches.Add((r.GetGuid(0),r.GetDecimal(1),r.GetDecimal(2)));}foreach(var b in branches){var journal=Guid.NewGuid();await using(var j=new NpgsqlCommand("INSERT INTO finance.journal_entry(id,branch_id,entry_no,posting_date,source_type,source_id,description,status,posted_by,posted_at,created_by,updated_by) VALUES(@jid,@branch,@no,current_date,'payroll',@run,'Payroll posting','posted',@actor,now(),@actor,@actor)",c,tx)){j.Parameters.AddWithValue("jid",journal);j.Parameters.AddWithValue("branch",b.Branch);j.Parameters.AddWithValue("no",BusinessCode.New("JRN"));j.Parameters.AddWithValue("run",id);j.Parameters.AddWithValue("actor",actor);await j.ExecuteNonQueryAsync();}await using(var lines=new NpgsqlCommand("INSERT INTO finance.journal_line(journal_entry_id,line_no,ledger_account_id,debit,credit,description,created_by,updated_by) VALUES(@j,1,@expense,@gross,0,'Payroll expense',@actor,@actor),(@j,2,@payable,0,@gross,'Salary payable',@actor,@actor)",c,tx)){lines.Parameters.AddWithValue("j",journal);lines.Parameters.AddWithValue("expense",expense);lines.Parameters.AddWithValue("payable",payable);lines.Parameters.AddWithValue("gross",b.Gross);lines.Parameters.AddWithValue("actor",actor);await lines.ExecuteNonQueryAsync();}}await using(var run=new NpgsqlCommand("UPDATE payroll.payroll_run SET status='posted',posted_by=@actor,posted_at=now(),updated_at=now(),updated_by=@actor WHERE id=@id AND status='approved'",c,tx)){run.Parameters.AddWithValue("id",id);run.Parameters.AddWithValue("actor",actor);if(await run.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Only approved payroll can be posted.");}await using(var results=new NpgsqlCommand("UPDATE payroll.employee_payroll_result SET status='posted',updated_at=now(),updated_by=@actor WHERE payroll_run_id=@id",c,tx)){results.Parameters.AddWithValue("id",id);results.Parameters.AddWithValue("actor",actor);await results.ExecuteNonQueryAsync();}await tx.CommitAsync();}
    private static async Task<NpgsqlConnection> Open(){var c=new NpgsqlConnection(StaticConnection.conn);await c.OpenAsync();return c;}private static string? S(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static Guid? G(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetGuid(i);private static decimal? D(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetDecimal(i);private static DateOnly? ND(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetFieldValue<DateOnly>(i);private static DateTimeOffset? DTO(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetFieldValue<DateTimeOffset>(i);private static void P(NpgsqlCommand q,string n,object? v)=>q.Parameters.AddWithValue(n,v??DBNull.Value);
}
